import{_ as l,c as a,o as i,ae as e}from"./chunks/framework.BbFa6TS3.js";const s=JSON.parse('{"title":"HTTP","description":"","frontmatter":{},"headers":[],"relativePath":"fe/default/http.md","filePath":"fe/default/http.md"}'),d={name:"fe/default/http.md"};function r(h,t,o,n,u,T){return i(),a("div",null,t[0]||(t[0]=[e('<h1 id="http" tabindex="-1">HTTP <a class="header-anchor" href="#http" aria-label="Permalink to &quot;HTTP&quot;">​</a></h1><p>HTTP（HyperText Transfer Protocol，超文本传输协议）是一种用于分布式、协作式和超媒体信息系统的应用层协议。HTTP 是 Web 数据通信的基础，它定义了客户端和服务器之间请求和响应的标准。</p><h3 id="http-特点" tabindex="-1">HTTP 特点 <a class="header-anchor" href="#http-特点" aria-label="Permalink to &quot;HTTP 特点&quot;">​</a></h3><ul><li>无状态 ：每个请求都是独立的，服务器不会保留之前请求的信息</li><li>可扩展 ：通过 HTTP 标头可以轻松扩展功能</li><li>客户端-服务器模式 ：由客户端发起请求，服务器返回响应</li><li>简单快速 ：客户端向服务器发送请求时，只需传送请求方法和路径</li><li>灵活 ：允许传输任意类型的数据对象</li></ul><h2 id="http-版本演进" tabindex="-1">HTTP 版本演进 <a class="header-anchor" href="#http-版本演进" aria-label="Permalink to &quot;HTTP 版本演进&quot;">​</a></h2><h3 id="http-1-0" tabindex="-1">HTTP/1.0 <a class="header-anchor" href="#http-1-0" aria-label="Permalink to &quot;HTTP/1.0&quot;">​</a></h3><ul><li>最早在 1996 年发布</li><li>每次请求都需要建立一个 TCP 连接</li><li>支持有限的请求方法（GET、POST、HEAD）</li><li>不支持持久连接</li></ul><h3 id="http-1-1" tabindex="-1">HTTP/1.1 <a class="header-anchor" href="#http-1-1" aria-label="Permalink to &quot;HTTP/1.1&quot;">​</a></h3><ul><li>1997 年发布，目前应用最广泛的版本</li><li>引入持久连接（Connection: keep-alive）</li><li>增加了更多请求方法（PUT、DELETE、OPTIONS 等）</li><li>支持管道化请求（pipelining）</li><li>引入内容协商机制</li><li>缓存控制机制更加完善</li></ul><h3 id="http-2" tabindex="-1">HTTP/2 <a class="header-anchor" href="#http-2" aria-label="Permalink to &quot;HTTP/2&quot;">​</a></h3><ul><li>2015 年发布</li><li>二进制分帧层，不再使用文本格式</li><li>多路复用，允许同时通过单一 TCP 连接发送多个请求</li><li>头部压缩，减少网络开销</li><li>服务器推送，允许服务器主动向客户端推送资源</li></ul><h3 id="http-3" tabindex="-1">HTTP/3 <a class="header-anchor" href="#http-3" aria-label="Permalink to &quot;HTTP/3&quot;">​</a></h3><ul><li>基于 QUIC 协议，使用 UDP 而非 TCP</li><li>改进的拥塞控制和丢包恢复机制</li><li>减少了连接建立的延迟</li><li>更好的移动网络支持</li></ul><h2 id="http-请求方法" tabindex="-1">HTTP 请求方法 <a class="header-anchor" href="#http-请求方法" aria-label="Permalink to &quot;HTTP 请求方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>描述</th><th>是否包含请求体</th><th>是否安全</th><th>是否幂等</th></tr></thead><tbody><tr><td>GET</td><td>获取资源</td><td>否</td><td>是</td><td>是</td></tr><tr><td>POST</td><td>提交数据</td><td>是</td><td>否</td><td>否</td></tr><tr><td>PUT</td><td>上传或替换资源</td><td>是</td><td>否</td><td>是</td></tr><tr><td>DELETE</td><td>删除资源</td><td>可选</td><td>否</td><td>是</td></tr><tr><td>HEAD</td><td>获取响应头</td><td>否</td><td>是</td><td>是</td></tr><tr><td>OPTIONS</td><td>获取支持的方法</td><td>否</td><td>是</td><td>是</td></tr><tr><td>PATCH</td><td>部分修改资源</td><td>是</td><td>否</td><td>否</td></tr><tr><td>CONNECT</td><td>建立隧道连接</td><td>否</td><td>否</td><td>否</td></tr><tr><td>TRACE</td><td>追踪请求路径</td><td>否</td><td>是</td><td>是</td></tr></tbody></table><h2 id="http-状态码" tabindex="-1">HTTP 状态码 <a class="header-anchor" href="#http-状态码" aria-label="Permalink to &quot;HTTP 状态码&quot;">​</a></h2><h3 id="_1xx-信息性状态码" tabindex="-1">1xx - 信息性状态码 <a class="header-anchor" href="#_1xx-信息性状态码" aria-label="Permalink to &quot;1xx - 信息性状态码&quot;">​</a></h3><ul><li>100 Continue ：服务器已收到请求头，客户端应继续发送请求体</li><li>101 Switching Protocols ：服务器正在切换协议</li></ul><h3 id="_2xx-成功状态码" tabindex="-1">2xx - 成功状态码 <a class="header-anchor" href="#_2xx-成功状态码" aria-label="Permalink to &quot;2xx - 成功状态码&quot;">​</a></h3><ul><li>200 OK ：请求成功</li><li>201 Created ：已创建新资源</li><li>204 No Content ：请求成功但没有返回内容</li></ul><h3 id="_3xx-重定向状态码" tabindex="-1">3xx - 重定向状态码 <a class="header-anchor" href="#_3xx-重定向状态码" aria-label="Permalink to &quot;3xx - 重定向状态码&quot;">​</a></h3><ul><li>301 Moved Permanently ：资源永久移动到新位置</li><li>302 Found ：资源临时移动到新位置</li><li>304 Not Modified ：资源未修改，可使用缓存</li></ul><h3 id="_4xx-客户端错误状态码" tabindex="-1">4xx - 客户端错误状态码 <a class="header-anchor" href="#_4xx-客户端错误状态码" aria-label="Permalink to &quot;4xx - 客户端错误状态码&quot;">​</a></h3><ul><li>400 Bad Request ：请求语法错误</li><li>401 Unauthorized ：需要身份验证</li><li>403 Forbidden ：服务器拒绝请求</li><li>404 Not Found ：资源不存在</li><li>405 Method Not Allowed ：不允许使用该请求方法</li><li>429 Too Many Requests ：请求过于频繁</li></ul><h3 id="_5xx-服务器错误状态码" tabindex="-1">5xx - 服务器错误状态码 <a class="header-anchor" href="#_5xx-服务器错误状态码" aria-label="Permalink to &quot;5xx - 服务器错误状态码&quot;">​</a></h3><ul><li>500 Internal Server Error ：服务器内部错误</li><li>502 Bad Gateway ：网关错误</li><li>503 Service Unavailable ：服务暂时不可用</li><li>504 Gateway Timeout ：网关超时</li></ul><h2 id="http-头部字段" tabindex="-1">HTTP 头部字段 <a class="header-anchor" href="#http-头部字段" aria-label="Permalink to &quot;HTTP 头部字段&quot;">​</a></h2><h3 id="通用头部" tabindex="-1">通用头部 <a class="header-anchor" href="#通用头部" aria-label="Permalink to &quot;通用头部&quot;">​</a></h3><ul><li>Cache-Control ：指定缓存机制</li><li>Connection ：控制网络连接选项</li><li>Date ：消息生成的日期和时间</li><li>Transfer-Encoding ：指定传输编码方式</li></ul><h3 id="请求头部" tabindex="-1">请求头部 <a class="header-anchor" href="#请求头部" aria-label="Permalink to &quot;请求头部&quot;">​</a></h3><ul><li>Accept ：指定客户端接受的内容类型</li><li>Accept-Encoding ：指定可接受的内容编码</li><li>Authorization ：包含身份验证信息</li><li>Host ：指定请求的服务器域名和端口</li><li>User-Agent ：客户端应用类型、操作系统、软件开发商等信息</li><li>Cookie ：之前由服务器通过 Set-Cookie 发送的 Cookie 信息</li></ul><h3 id="响应头部" tabindex="-1">响应头部 <a class="header-anchor" href="#响应头部" aria-label="Permalink to &quot;响应头部&quot;">​</a></h3><ul><li>Access-Control-Allow-Origin ：指定允许跨域的域名</li><li>ETag ：资源的特定版本的标识符</li><li>Location ：用于重定向的 URL</li><li>Set-Cookie ：服务器发送的 Cookie</li><li>WWW-Authenticate ：指定身份验证方案</li></ul><h3 id="实体头部" tabindex="-1">实体头部 <a class="header-anchor" href="#实体头部" aria-label="Permalink to &quot;实体头部&quot;">​</a></h3><ul><li>Content-Encoding ：指定内容的编码方式</li><li>Content-Length ：指定内容的长度</li><li>Content-Type ：指定内容的类型</li><li>Expires ：指定内容的过期时间</li><li>Last-Modified ：指定内容的最后修改时间</li></ul><h2 id="http-缓存机制" tabindex="-1">HTTP 缓存机制 <a class="header-anchor" href="#http-缓存机制" aria-label="Permalink to &quot;HTTP 缓存机制&quot;">​</a></h2><h3 id="强缓存" tabindex="-1">强缓存 <a class="header-anchor" href="#强缓存" aria-label="Permalink to &quot;强缓存&quot;">​</a></h3><ul><li>Expires ：指定资源过期的绝对时间</li><li>Cache-Control ：更精确的缓存控制 <ul><li>max-age ：指定资源有效期</li><li>no-cache ：需要验证才能使用缓存</li><li>no-store ：禁止缓存</li></ul></li></ul><h3 id="协商缓存" tabindex="-1">协商缓存 <a class="header-anchor" href="#协商缓存" aria-label="Permalink to &quot;协商缓存&quot;">​</a></h3><ul><li>Last-Modified/If-Modified-Since ：基于资源修改时间的验证</li><li>ETag/If-None-Match ：基于资源内容的验证</li></ul><h2 id="https" tabindex="-1">HTTPS <a class="header-anchor" href="#https" aria-label="Permalink to &quot;HTTPS&quot;">​</a></h2><p>HTTPS（HTTP Secure）是 HTTP 协议的安全版本，它通过 SSL/TLS 协议进行加密通信。</p><h3 id="https-的优势" tabindex="-1">HTTPS 的优势 <a class="header-anchor" href="#https-的优势" aria-label="Permalink to &quot;HTTPS 的优势&quot;">​</a></h3><ul><li>数据加密 ：防止数据被窃听</li><li>数据完整性 ：防止数据被篡改</li><li>身份认证 ：确保与正确的服务器通信</li></ul><h3 id="https-的工作原理" tabindex="-1">HTTPS 的工作原理 <a class="header-anchor" href="#https-的工作原理" aria-label="Permalink to &quot;HTTPS 的工作原理&quot;">​</a></h3><ol><li>握手阶段 ：客户端与服务器建立安全连接</li><li>证书验证 ：客户端验证服务器的数字证书</li><li>密钥交换 ：安全地交换对称加密的密钥</li><li>加密通信 ：使用对称加密进行后续通信</li></ol><h2 id="http-安全" tabindex="-1">HTTP 安全 <a class="header-anchor" href="#http-安全" aria-label="Permalink to &quot;HTTP 安全&quot;">​</a></h2><h3 id="常见的-http-安全问题" tabindex="-1">常见的 HTTP 安全问题 <a class="header-anchor" href="#常见的-http-安全问题" aria-label="Permalink to &quot;常见的 HTTP 安全问题&quot;">​</a></h3><ul><li>跨站脚本攻击（XSS） ：注入恶意脚本</li><li>跨站请求伪造（CSRF） ：伪造用户请求</li><li>中间人攻击 ：拦截并可能修改通信内容</li><li>会话劫持 ：窃取用户会话标识</li></ul><h3 id="安全最佳实践" tabindex="-1">安全最佳实践 <a class="header-anchor" href="#安全最佳实践" aria-label="Permalink to &quot;安全最佳实践&quot;">​</a></h3><ul><li>使用 HTTPS 加密通信</li><li>实施内容安全策略（CSP）</li><li>使用 HTTP 严格传输安全（HSTS）</li><li>设置适当的 Cookie 属性（Secure, HttpOnly, SameSite）</li><li>实施适当的身份验证和授权机制</li></ul>',51)]))}const P=l(d,[["render",r]]);export{s as __pageData,P as default};
